async function getPlaylists(force=false){
 if(state.playlists&&!force)return state.playlists;
 const r=await fetch(BASE+'/api/playlists');const b=await r.json();state.playlists=(b.playlists||[]);return state.playlists;
}
async function getCurators(force=false){
 if(state.curators&&!force)return state.curators;
 const r=await fetch(BASE+'/api/curators');const b=await r.json();state.curators=(b.curators||[]);return state.curators;
}
function fit(p,genre,moods=[],comp=[]){
 const reasons=[],caveats=[];const g=norm(genre),primary=norm(p.primary_genre),secondary=(p.secondary_genres||[]).map(norm);
 const genrePrimary=Boolean(g&&primary===g),genreSecondary=Boolean(g&&secondary.includes(g));
 const genreRelated=Boolean(g&&!genrePrimary&&!genreSecondary&&[primary,...secondary].some(x=>x&&((x.includes(g)||g.includes(x)))));
 if(genrePrimary)reasons.push('Primary genre aligns: '+p.primary_genre);
 else if(genreSecondary)reasons.push('Genre appears in this playlist’s secondary lanes');
 else if(genreRelated)reasons.push('Related genre lane');
 else if(g)caveats.push('Genre is outside the playlist’s stated lane');
 const pm=(p.moods||[]).map(norm),moodHits=moods.filter(m=>pm.includes(norm(m)));
 if(moodHits.length>=2)reasons.push('Multiple mood signals align: '+moodHits.slice(0,3).join(', '));
 else if(moodHits.length===1)reasons.push('Mood overlap: '+moodHits[0]);
 else if(moods.length&&pm.length)caveats.push('No exact mood overlap in the current profile');
 const pa=(p.anchor_artists||[]).map(norm),artistHits=comp.filter(a=>pa.includes(norm(a)));
 if(artistHits.length)reasons.push('Comparable-artist overlap: '+artistHits.slice(0,2).join(', '));
 const materialGenre=genrePrimary||genreSecondary;
 const corroboration=moodHits.length>=2||artistHits.length>0;
 const materialContradiction=Boolean(g&&!genrePrimary&&!genreSecondary&&!genreRelated);
 let band='No band';
 if(materialContradiction)band='Long shot';
 else if(materialGenre&&corroboration&&!caveats.length)band='Strong fit';
 else if(materialGenre||((genreRelated||moodHits.length>0)&&reasons.length>=2))band='Worth a look';
 else if(genreRelated||moodHits.length>0)band='Long shot';
 return {band,reasons:reasons.slice(0,3),caveats:caveats.slice(0,2),hasEvidence:band!=='No band'};
}
