function authForm(){return '<div class="auth-card"><div class="eyebrow">Curator account</div><h2>Sign in or create an account.</h2><div class="form-grid"><div class="field full"><label>Email</label><input id="auth-email" type="email"></div><div class="field full"><label>Password</label><input id="auth-password" type="password"></div></div><div style="display:flex;gap:8px;margin-top:16px"><button id="auth-signin" class="button dark">Sign in</button><button id="auth-signup" class="button">Create account</button></div><div id="auth-message"></div></div>'}
async function curatorWorkspace(mode='apply'){
 if(!state.session)return authForm();
 const r=await fetch(BASE+'/api/curator',{headers:{Authorization:'Bearer '+state.session.access_token}});
 const d=await r.json();
 if(!r.ok)return '<div class="notice error">'+esc(d.error||'Curator workspace unavailable')+'</div>';
 let spotifyStatus={connected:false,connection:null};
 if(mode==='apply'){
   try{
     const sr=await fetch(BASE+'/api/spotify',{method:'POST',headers:{Authorization:'Bearer '+state.session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action:'curator_status'})});
     if(sr.ok)spotifyStatus=await sr.json();
   }catch{}
 }

 if(mode==='apply'&&!d.profile){
   return '<div class="auth-card"><div class="eyebrow">Step 1 · curator identity</div><h2>Apply to the Founding Curator Beta.</h2><div class="form-grid"><div class="field"><label>Display name</label><input id="apply-name"></div><div class="field"><label>Handle</label><input id="apply-handle"></div><div class="field full"><label>Editorial bio</label><textarea id="apply-bio"></textarea></div><div class="field full"><label>Genres you curate</label><input id="apply-genres" placeholder="future bass, melodic dubstep"></div></div><div class="notice" style="margin-top:14px">You are applying to CuratorOS, not to the BVSS FVM label. Editorial decisions remain yours.</div><button id="apply-submit" class="button dark" style="margin-top:16px">Submit application</button><div id="apply-message"></div></div>';
 }

 if(mode==='apply'){
   const live=await getPlaylists();
   const genres=[...new Set(live.flatMap(p=>[p.primary_genre,...(p.secondary_genres||[])]).filter(Boolean))].sort();
   const playlistRows=(d.playlists||[]).map(p=>{
     const claim=(d.claims||[]).find(x=>x.playlist_id===p.id);
     return '<article class="detail-card curator-playlist" data-playlist="'+esc(p.id)+'" style="margin-top:16px">'+
       '<div class="eyebrow-row"><span>'+esc(p.verification_status)+' claim</span><span>'+esc(p.submission_status)+'</span></div>'+
       '<h2>'+esc(p.canonical_name)+'</h2>'+
       (claim?'<div class="notice">'+(claim.status==='verified'?'Ownership verified.':'Description verification code: <strong>'+esc(claim.verification_code)+'</strong>')+'</div>':'')+
       '<div class="form-grid" style="margin-top:14px">'+
         '<div class="field"><label>Primary genre</label><select data-field="primary_genre">'+genres.map(g=>'<option '+(g===p.primary_genre?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select></div>'+
         '<div class="field"><label>Secondary genres</label><input data-field="secondary_genres" value="'+esc((p.secondary_genres||[]).join(', '))+'"></div>'+
         '<div class="field"><label>Moods</label><input data-field="moods" value="'+esc((p.moods||[]).join(', '))+'"></div>'+
         '<div class="field"><label>Hard NO tags</label><input data-field="hard_no_tags" value="'+esc((p.hard_no_tags||[]).join(', '))+'" placeholder="covers, ai vocals"></div>'+
         '<div class="field"><label>Review SLA hours</label><input data-field="review_sla_hours" type="number" min="1" max="720" value="'+esc(p.review_sla_hours??168)+'"></div>'+
         '<div class="field"><label>Max open routes</label><input data-field="max_open_routes" type="number" min="1" max="10000" value="'+esc(p.max_open_routes??100)+'"></div>'+
         '<div class="field"><label>Cooldown days</label><input data-field="route_cooldown_days" type="number" min="0" max="365" value="'+esc(p.route_cooldown_days??30)+'"></div>'+
         '<div class="field"><label><input data-field="accepts_unreleased" type="checkbox" '+(p.accepts_unreleased?'checked':'')+'> Accept unreleased</label><label><input data-field="accepts_explicit" type="checkbox" '+(p.accepts_explicit?'checked':'')+'> Accept explicit</label></div>'+
         '<div class="field full"><label>Submission criteria</label><textarea data-field="submission_criteria">'+esc(p.submission_criteria||'')+'</textarea></div>'+
       '</div>'+
       '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px"><button class="button dark small save-criteria" data-playlist="'+esc(p.id)+'">Save criteria</button>'+
       (claim&&claim.status!=='verified'?'<button class="button small request-verify" data-playlist="'+esc(p.id)+'">I added the code · request verification</button>':'')+
       (p.verification_status==='verified'?'<button class="button small toggle-playlist" data-playlist="'+esc(p.id)+'" data-next="'+(p.submission_status==='open'?'paused':'open')+'">'+(p.submission_status==='open'?'Pause submissions':'Open submissions')+'</button>':'')+
       '</div><div class="provenance playlist-action-message" style="margin-top:9px"></div></article>';
   }).join('');

   return '<div class="detail-grid"><div><div class="detail-card"><div class="eyebrow">Curator identity</div><h2>'+esc(d.profile.display_name)+'</h2><p>Status: <strong>'+esc(d.profile.status)+'</strong></p><p>'+esc(d.profile.bio||'')+'</p><div class="notice">CuratorOS is neutral infrastructure. BVSS FVM is Verified Network #001, not the owner of your profile.</div></div>'+
     '<div class="section-head" style="margin-top:28px;margin-bottom:0"><div><div class="eyebrow">Your supply</div><h2>Playlist claims & routing criteria</h2></div></div>'+
     (playlistRows||'<div class="detail-card" style="margin-top:16px">No playlists added yet.</div>')+
     '</div><aside><div class="detail-card"><div class="eyebrow">Preferred verification</div><h2>Connect Spotify owner account.</h2><p>CuratorOS requests only <strong>playlist-read-private</strong>. It cannot add, remove or reorder tracks.</p>'+
     (spotifyStatus.connected
       ? '<div class="notice">Connected as Spotify account <strong>'+esc(spotifyStatus.connection?.spotify_account_id||'connected')+'</strong>.<br>Last verified: '+esc(spotifyStatus.connection?.last_verified_at?date(spotifyStatus.connection.last_verified_at):'Not yet')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:12px"><button id="spotify-verify" class="button dark small">Verify my registered playlists</button><button id="spotify-disconnect" class="button small">Disconnect</button></div>'
       : spotifyStatus.spotify_app_configured
         ? '<button id="spotify-connect" class="button dark" style="margin-top:12px">Connect Spotify · read-only</button>'
         : '<div class="notice">Spotify OAuth is prepared but not activated for this environment yet. Use the description-code verification below; no playlist editing permission is required.</div>')+
     '<div id="spotify-message" class="provenance" style="margin-top:10px"></div></div>'+
     '<div class="detail-card" style="margin-top:16px"><div class="eyebrow">Fallback verification</div><h2>Add a playlist.</h2><div class="field"><label>Spotify playlist URL</label><input id="claim-url"></div><div class="field"><label>Playlist name</label><input id="claim-name"></div><div class="field"><label>Primary genre</label><select id="claim-genre"><option value="">Choose…</option>'+genres.map(g=>'<option>'+esc(g)+'</option>').join('')+'</select></div><button id="claim-add" class="button dark" style="margin-top:14px">Add playlist</button><div id="claim-message"></div><p class="provenance">If you do not connect Spotify, CuratorOS can verify ownership with a temporary code in the playlist description. Neither method grants CuratorOS permission to edit your playlist.</p></div></aside></div>';
 }

 const routes=d.routes||[];
 return '<div><div class="section-head"><div><div class="eyebrow">Curator workspace</div><h2>Inbox</h2></div><span class="provenance">Account: '+esc(d.profile?.status||'unknown')+'</span></div>'+
   (routes.length?routes.map(r=>{const p=r.placement;const decisionControls=['queued','opened','hold'].includes(r.status)?'<div class="decision-panel" style="margin-top:14px"><div class="form-grid"><div class="field"><label>Hold reason</label><select class="hold-reason"><option value="">Choose when holding…</option><option>Another listen needed</option><option>Revisit after release</option><option>Need more context</option></select></div><div class="field"><label>Revisit date</label><input class="hold-date" type="date" min="'+new Date(Date.now()+86400000).toISOString().slice(0,10)+'" max="'+new Date(Date.now()+30*86400000).toISOString().slice(0,10)+'"></div><div class="field"><label>Decline reason</label><select class="decline-reason"><option value="">Choose when declining…</option><option value="energy_mismatch">Energy mismatch</option><option value="not_my_genre_lane">Not my genre lane</option><option value="production_not_ready">Production not ready</option><option value="too_similar_to_recent_adds">Too similar to recent adds</option><option value="wrong_mood">Wrong mood</option><option value="vocal_style">Vocal style</option><option value="mix_master">Mix / master</option><option value="other">Other</option></select></div><div class="field"><label>Optional note</label><input class="decision-note" maxlength="280" placeholder="Useful context for this route"></div></div><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="button dark small curator-decision" data-route="'+esc(r.id)+'" data-decision="accept">Accept</button><button class="button small curator-decision" data-route="'+esc(r.id)+'" data-decision="hold">Hold</button><button class="button small curator-decision" data-route="'+esc(r.id)+'" data-decision="reject">Decline</button></div><div class="provenance decision-message" style="margin-top:8px"></div></div>':p?.status==='scheduled'?'<div style="margin-top:14px"><button class="button dark small report-added" data-placement="'+esc(p.id)+'">I’ve added it</button></div>':p?.status==='pending_verification'?'<div class="notice" style="margin-top:14px">Pending verification. CuratorOS has not called this Live yet.</div>':p?.status==='live'?'<div class="notice" style="margin-top:14px">Verified Live'+(p.actual_position!=null?' · Position '+esc(Number(p.actual_position)+1):'')+'</div>':'';return '<article class="inbox-card"><div class="eyebrow-row"><span>'+esc(r.bvss_playlists?.canonical_name||'Playlist')+'</span><span>'+esc(p?.status||r.status)+'</span></div><h3>'+esc(r.bvss_submissions?.song_title||'Submission')+' — '+esc(r.bvss_submissions?.artist_name||'Artist')+'</h3>'+(r.fit_band?fitBadge(r.fit_band):'')+chips((r.fit?.reasons||r.match_reasons||[]).map(x=>typeof x==='string'?x:(x.label||'Fit evidence')).slice(0,3))+'<div class="provenance">This route is visible only to the curator authorized for this playlist.</div>'+decisionControls+'</article>'}).join(''):'<div class="detail-card">No assigned routes yet.</div>')+
   '</div>';
}

